grid={}
phase='rev';fwd_left=0.0;last_touch=0
look_seq=[(-23,1.0),(43,0.5),(-23,1.0),(-65,0.5),(150,0.6),(-23,1.0),(-150,0.6)]
li=0;lt=0.0
tgt=None;axis=None;n=0

def wrap(a):
    return (a+180.0)%360.0-180.0

def clip(x,a,b):
    return max(a,min(b,x))

def tw(x,y):
    c=math.cos(TH);s=math.sin(TH)
    return (X+x*c-y*s, Y+x*s+y*c)

def control(obs):
    global X,Y,TH,phase,fwd_left,last_touch,li,lt,tgt,axis,n
    n+=1
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps'];st=obs['steer_deg']
    TH+=v*math.tan(math.radians(st))/2.75*dt
    X+=v*math.cos(TH)*dt;Y+=v*math.sin(TH)*dt
    views=obs.get('views') or {}
    for name,vw in views.items():
        if name=='periphery' or not vw: continue
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]):
                if d>15: continue
                px=ox+d*math.cos(math.radians(b));py=oy+d*math.sin(math.radians(b))
                wx,wy=tw(px,py)
                grid[(round(wx/0.2),round(wy/0.2))]=(wx,wy)
            tc=vw.get('target_corners') or []
            if len(tc)==4:
                P=[]
                for b,d in tc:
                    P.append(tw(ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b))))
                pr=[]
                for i in range(4):
                    for j in range(i+1,4):
                        dx=P[j][0]-P[i][0];dy=P[j][1]-P[i][1]
                        pr.append((math.hypot(dx,dy),math.degrees(math.atan2(dy,dx))))
                pr.sort()
                axis=pr[3][1]
                cx=sum(p[0] for p in P)/4;cy=sum(p[1] for p in P)/4
                tgt=(cx,cy) if tgt is None else (0.7*tgt[0]+0.3*cx,0.7*tgt[1]+0.3*cy)
