            c=math.cos(math.radians(ax));s=math.sin(math.radians(ax))
            dx=tgt[0]-rx;dy=tgt[1]-ry
            al=dx*c+dy*s;lat=-dx*s+dy*c
            alpha=ax+math.degrees(math.atan2(lat,max(al,1.5)))
