    hd=clip(-1.0*e,-30,30)
    hr=math.radians(hd)
    deq=math.degrees(math.atan(2.75*math.sin(hr)/(2.6+1.05*math.cos(hr))))
    steer=clip(deq+2.0*(h-hd),-34,34)
    spd=-1.0
    if res[best][1]<3 or abs(h-hd)>15: spd=-0.6
    if n%20==0:
        print('t%.1f h%.1f hd%.1f e%.1f L%.1f st%.1f tgt%s ax%s'%(obs['t'],h,hd,e,res[best][1],steer,tgt is not None,axis))
    return (steer,spd,look)

