                pts.append((t,X+px*c-py*s,Y+px*s+py*c))
        except Exception:
            pass
    pts=[p for p in pts if t-p[0]<10.0][-900:]
    rig=obs['rig']
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        ex,ey=rig['eye']; br=math.radians(tg['bearing_deg']); d=tg['dist_m']
        px=ex+d*math.cos(br); py=ey+d*math.sin(br)
        wx=X+px*c-py*s; wy=Y+px*s+py*c
