        else: tgt=(0.8*tgt[0]+0.2*wx,0.8*tgt[1]+0.2*wy)
    hitch=obs['hitch_deg']
    rx,ry=rig['trailer_rear']; th=rig['trailer_heading_deg']
    backd=180.0+th; back=math.radians(backd)
    local=[]
    for _,wx,wy in pts:
        dx=wx-X; dy=wy-Y
        vx=dx*c+dy*s; vy=-dx*s+dy*c
        local.append((vx-rx,vy-ry))
    res=[]
    for a in range(-60,61,3):
        ang=back+math.radians(a); ca=math.cos(ang); sa=math.sin(ang)
        df=10.0
        for qx,qy in local:
            l=qx*ca+qy*sa
            if l<=0 or l>=df: continue
            lat=-qx*sa+qy*ca
            if abs(lat)<1.4: df=l
        res.append((a,df))
    best=max(d for a,d in res)
    cands=[a for a,d in res if d>=best-0.5]
    runs=[];cur=[cands[0]]
    for a in cands[1:]:
        if a-cur[-1]<=3: cur.append(a)
        else: runs.append(cur); cur=[a]
    runs.append(cur)
    mids=[(r[0]+r[-1])/2.0 for r in runs]
    astar=min(mids,key=lambda m: abs(m-ahist))
