    if tgt is not None and rem<10:
        dx=tgt[0]-X; dy=tgt[1]-Y
        vx=dx*c+dy*s; vy=-dx*s+dy*c
        ta=wrap(math.degrees(math.atan2(vy-ry,vx-rx))-backd)
        if abs(ta)<60: astar=ta
    ahist=0.7*ahist+0.3*astar
    look=170
    if phase=='rev' and abs(hitch)>45:
        phase='fwd'
    if phase=='fwd':
        if abs(hitch)<8: phase='rev'
        else: return (0.0,1.0,look)
    hd=clamp(0.8*ahist,-30,30)
    steer=clamp(2.5*(hitch-hd),-45,45)
    sp=-1.0
    if best<3 or abs(hitch-hd)>15: sp=-0.6
    if rem<4: sp=-0.5
    if rem<-0.8:
        if not woke:
            woke=True
            try: wake('past bay centre, stopping')
            except Exception: pass
        return (0.0,0.0,look)
    return (steer,sp,look)

